insert into public.event_series (id, name, frequency, start_year, end_year, description, catalog_category, catalog_status, governing_body, region, home_venue, country, former_names, disciplines, sources, confidence) values
  ('a-robs-smash-life-banked-slalom', 'A-Rob''s Smash Life Banked Slalom', 'annual', NULL, NULL, 'Fundraiser banked slalom at Lost Trail, Montana celebrating the late snowboarders Aaron Robinson and Dillon Candelaria. The 2026 edition is listed for March 21.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Lost Trail Powder Mountain', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('air-and-style', 'Air + Style', 'annual', 1994, 2019, 'Started at the Bergisel ski-jump stadium in Innsbruck by Charly Weger and Andrew Hourmont as a single straight-jump contest with a USD 10,000 purse, and grew into the biggest stadium big air of the 1990s and 2000s. A fatal crowd crush after the 4 December 1999 edition killed five people (a sixth died four years later) and led the city of Innsbruck to refuse further events, moving the contest to Seefeld (2000-2004) and then Munich (2005-2007). It was a TTR 6Star and later became its own multi-city tour with stops in Beijing (from 2010) and Los Angeles (from 2015). Shaun White became majority owner in 2014. Edition numbering is inconsistent between sources.', 'major-contest', 'dormant', 'independent', 'global', NULL, 'multiple', ARRAY['Flying High Air & Style Contest','Red Bull Air & Style','Quiksilver Air & Style','G-Shock Air & Style','Nokia Air & Style','Billabong Air & Style','Nike 6.0 Air & Style','Oakley & Shaun White Present Air & Style','Opel Air + Style']::text[], ARRAY['big-air','quarterpipe']::text[], ARRAY['https://en.wikipedia.org/wiki/Air_%26_Style','https://de.wikipedia.org/wiki/Air_%26_Style','https://austria-forum.org/af/AustriaWiki/Air_&_Style','https://whitelines.com/events/air-style-innsbruck','https://www.innsbruck.info/blog/en/events/air-and-style2016/','https://www.tt.com/artikel/16237751/das-erbe-des-air-style-snowboarder-fliegen-wieder-auf-bergisel-ab','https://collectivemag.de/air-style-vom-bergisel-stadion-in-die-ganze-welt-pid16548/']::text[], 'verified'),
  ('air-nation-freestyle-tour', 'Air Nation Freestyle Tour', 'tour', NULL, NULL, 'Canada Snowboard''s national freestyle tour. Recurring stops have included Sun Peaks, Mont Tremblant, Stoneham, Mt St Louis Moonstone, Horseshoe Valley and WinSport Canada Olympic Park in Calgary; the final stop normally carries the national championship.', 'tour-series', 'active', 'Canada Snowboard', 'north-america', NULL, 'Canada', ARRAY['Sport Chek Air Nation Freestyle Tour']::text[], ARRAY['slopestyle','halfpipe','big-air','rail-jam']::text[], ARRAY['https://www.canadasnowboard.ca/en/events/freestyletour/','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259']::text[], 'verified'),
  ('argentina-snowboard-tour', 'Argentina Snowboard Tour', 'tour', NULL, NULL, 'Described by the WSF as the largest circuit of snowboard events in South America, run by Argentina''s national snowboard association with World Snowboard Tour ranking points. Stops mix urban big airs in Buenos Aires with Patagonian and Andean resorts (Cerro Chapelco, Cerro Bayo, Cerro Catedral, La Hoya); most are open entry, with one invitational.', 'tour-series', 'unconfirmed', 'Asociacion Argentina de Snowboard (AAS)', 'south-america', NULL, 'Argentina', ARRAY['AST']::text[], ARRAY['big-air','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/the-argentina-snowboard-tour-ast/','https://www.worldsnowboardfederation.org/third-tour-stop-argentina-snowboard-tour-2014/']::text[], 'likely'),
  ('atlas-open-val-saint-come', 'Atlas Open', 'annual', 1993, NULL, 'Long-running Quebec contest at Val Saint-Come, first held in 1993 and previously known as the Coupe Val St-Come and the Royal Rumble, per SnowboardQuebec''s history of the sport in the province. Disciplines and end date not sourced.', 'legacy-contest', 'unconfirmed', 'independent', 'north-america', 'Val Saint-Come', 'Canada', ARRAY['Coupe Val Saint-Come','Royal Rumble']::text[], ARRAY['other']::text[], ARRAY['https://www.snowboardquebec.com/histoire/']::text[], 'likely'),
  ('audi-nines', 'Audi Nines', 'annual', 2008, NULL, 'Invitational session founded by Nico Zacek at the Nebelhorn, Oberstdorf in 2008 as a nine-rider freeski gathering. Nine Queens (women) was added at Serfaus-Fiss-Ladis in 2011; Nine Knights moved to Livigno in 2012; snowboarders joined the roster in 2014 when Knights and Queens were first combined. Rebranded Nine Royals in 2017 (Watles) and Audi Nines from 2018 (Soelden/Obergurgl). Riders are judged on custom jump, hip and transition features rather than a fixed course format.', 'major-contest', 'unconfirmed', 'independent', 'europe', NULL, 'multiple', ARRAY['Nine Knights','Nine Queens','Knights & Queens','Suzuki Nine Royals','The Nines']::text[], ARRAY['big-air','hip','slopestyle','other']::text[], ARRAY['https://www.downdays.eu/articles/audi-nines-retrospective/']::text[], 'likely'),
  ('audi-snowboard-series', 'Audi Snowboard Series', 'tour', NULL, NULL, 'The Swiss federation''s national snowboard tour, more than 30 events a season across freestyle, boardercross and race, positioned as a junior pathway to the international elite. The Swiss Championships in all three disciplines close the series.', 'tour-series', 'unconfirmed', 'Swiss-Ski', 'europe', NULL, 'Switzerland', NULL, ARRAY['slopestyle','halfpipe','boardercross','other']::text[], ARRAY['https://www.worldsnowboardfederation.org/audi-snowboard-series/']::text[], 'likely'),
  ('b4bc-snowboard-and-music-festival', 'B4BC Snowboard + Music Festival', 'annual', 1996, NULL, 'Boarding for Breast Cancer''s founding event. B4BC was created in 1996 by Lisa Hudson with Dawn Kish, Kathleen Gasparini and others in memory of Monica Steward, a 26-year-old snowboarder who died of breast cancer after a delayed diagnosis; the first B4BC Snowboard + Music Festival was held in April 1996 with pro riders Tina Basich and Shannon Dunn as spokeswomen. B4BC states the festivals have raised over $1,000,000 since 1996. The competition format of the festivals is not stated in the sources found, and the snowboard festival no longer appears on B4BC''s current events calendar, which is now skate- and clinic-led (Love Your Peaks winter series, Summer Skate Series).', 'grassroots-contest', 'dormant', 'independent', 'north-america', NULL, 'USA', NULL, NULL, ARRAY['https://b4bc.org/about/','https://b4bc.org/events/']::text[], 'likely'),
  ('baldy-banked-slalom', 'Baldy Banked Slalom', 'annual', NULL, NULL, 'Banked slalom on Bald Mountain at Sun Valley, Idaho. Local Freshies describes the March 7, 2026 edition as ''now in its 14th year''.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Sun Valley Resort', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('bc-snowboard-provincial-series', 'BC Snowboard Provincial Series', 'annual', NULL, NULL, 'British Columbia''s provincial competition series, run by BC Snowboard (based in Kelowna) in slopestyle and snowboardcross, with an overall series title. Host resorts in recent seasons have been Big White, Silver Star, Sun Peaks and Whistler Blackcomb. BC Snowboard also sanctions the Neil Edgeworth Memorial Banked Slalom and hosts NorAm, national championship and para World Cup events.', 'grassroots-contest', 'active', 'BC Snowboard', 'north-america', NULL, 'Canada', ARRAY['Ride On Provincial Series']::text[], ARRAY['slopestyle','boardercross']::text[], ARRAY['https://www.bcsnowboard.com/events/','https://www.bcsnowboard.com/about/','https://www.bcsnowboard.com/2025-event-results/','https://www.bcsnowboard.com/events/provincial-events/']::text[], 'verified'),
  ('big-white-para-snowboard-world-cup', 'Big White Para Snowboard World Cup', 'annual', NULL, NULL, 'Big White''s annual para-snowboard international, on the TELUS Park course near Kelowna. Big White has supported para snowboarding since 2012 and by the 2018-19 season was hosting for a seventh consecutive year; it also staged the 2017 World Para Snowboard Championships and the 2025 FIS Para Snowboard World Championships, the latter including the first team event in para snowboard history. Governance moved from the IPC to FIS during the period.', 'tour-stop', 'active', 'FIS', 'north-america', 'Big White Ski Resort', 'Canada', ARRAY['World Para Snowboard World Cup Big White']::text[], ARRAY['boardercross','banked-slalom','team']::text[], ARRAY['https://www.canadasnowboard.ca/en/news/?id=1147','https://www.canadasnowboard.ca/en/news/?id=1258','https://www.canadasnowboard.ca/en/news/?id=1259','https://www.bigwhite.com/explore-big-white/blog/mountain-news/fis-pswc-25','https://www.canadasnowboard.ca/en/news/?id=1213']::text[], 'verified'),
  ('blue-mountain-fis-snowboard-world-cup', 'Blue Mountain FIS Snowboard World Cup', 'annual', NULL, NULL, 'Ontario''s World Cup venue at Collingwood. Hosted a team snowboardcross World Cup qualification event in February 2013 and a parallel giant slalom World Cup in 2020; also the host of the Canadian alpine national championships in 2018 and 2019.', 'tour-stop', 'unconfirmed', 'FIS', 'north-america', 'Blue Mountain Resort', 'Canada', NULL, ARRAY['boardercross','team','parallel-giant-slalom']::text[], ARRAY['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=2013&categorycode=WC&nationcode=CAN','https://olympic.ca/2019/10/24/winter-competitions-coming-to-canada-in-2019-20/','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259']::text[], 'likely'),
  ('bomb-hole-cup', 'The Bomb Hole Cup', 'annual', 2022, NULL, 'Two-day event at Brighton Resort, Utah, run with The Bomb Hole podcast: day one is a banked slalom on custom-built berms, day two an open-jam park showdown. Described as the fifth annual event in 2026; the 2027 edition is announced for April 3-4.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Brighton Resort', 'USA', NULL, ARRAY['banked-slalom','jib']::text[], ARRAY['https://www.brightonresort.com/events/the-bomb-hole-cup','https://www.snowboard.international/features/north-america-snowboard-events-2025-26/','https://thebombhole.com/blogs/bombhole-community/banked-slalom-bomb-hole-cup-2025-at-brighton-utah']::text[], 'likely'),
  ('bomber-banked-slalom', 'Bomber Banked Slalom', 'annual', NULL, NULL, 'Community banked slalom at Mission Ridge, Washington, on the Katsuk run at the summit off Chair 2, built by the resort''s park department. Capped at 250 snowboarders across 14 age and gender divisions including Open Pro and Pro Masters. The March 28-29, 2026 edition was billed as the 13th annual.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Mission Ridge Ski and Board Resort', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://www.missionridge.com/event/bomber-banked-slalom/']::text[], 'likely'),
  ('bucket-banked-slalom', 'Bucket Banked Slalom', 'annual', NULL, NULL, 'Banked slalom at Winter Park, Colorado run by the Winter Park Competition Center in memory of local rider and Comp Center alum Ben Lynch, as a fundraiser for the Grand Foundation''s H.O.P.E. Fund. Two runs, best time counts; amateur age divisions plus adaptive and pro categories. Organisers state over $119,305 raised to date.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Winter Park Resort', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://www.winterparkresort.com/things-to-do/competition-center/comp-center-events/bucket-banked-slalom']::text[], 'likely'),
  ('burton-australian-open', 'Burton Australian Open', 'annual', NULL, NULL, 'The Australian stop of the Burton Global Open Series, held at Perisher Blue in the Southern Hemisphere winter. Only the 2008 edition could be confirmed from a source opened for this pass.', 'tour-stop', 'unconfirmed', 'brand-run', 'oceania', 'Perisher Blue', 'Australia', NULL, NULL, ARRAY['https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[], 'likely'),
  ('burton-canadian-open', 'Burton Canadian Open Snowboarding Championships', 'annual', NULL, NULL, 'The Canadian stop of the Burton Global Open Series, held at Canada Olympic Park in Calgary, Alberta and rated 5Star on the Swatch TTR World Snowboard Tour.', 'tour-stop', 'unconfirmed', 'brand-run', 'north-america', 'Canada Olympic Park', 'Canada', NULL, ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://whitelines.com/archive/news/burton-global-open-series-08-09.html','https://onboardmag.com/news/snowboarding-events/burton-canadian-open-slopestyle.html','https://www.worldsnowboardfederation.org/registration-open-for-ttr-world-snowboard-tour-events/']::text[], 'likely'),
  ('burton-european-open', 'Burton European Open', 'annual', 1999, 2015, 'Burton''s European flagship and for most of its life the highest-rated (6Star) event on the Swatch TTR World Snowboard Tour in Europe. It began in the Innsbruck area of Austria, moved through Fieberbrunn and Livigno, and settled at Laax, Switzerland from 2005. Burton did not run the event for winter 2016 while re-evaluating its European platform, and the Laax Open took its place and its venue.', 'major-contest', 'defunct', 'brand-run', 'europe', 'Laax', 'multiple', NULL, ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.burton.com/blogs/the-burton-blog/10-years-laax-open/','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html','https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://onboardmag.com/news/european-news/laax-set-to-host-laax-open-2016.html','https://whitelines.com/events/burton-european-open']::text[], 'verified'),
  ('burton-global-open-series', 'Burton Global Open Series', 'tour', 2006, 2011, 'The umbrella that linked Burton''s national Open events into one ranked season, with an overall series title decided at the US Open. Member events across the seasons documented here were the Burton New Zealand Open, Burton Australian Open, Burton Canadian Open, Burton European Open, the Nissan X-Trail Nippon Open in Japan and the Burton US Open. Series champions received USD 100,000 each, described at the time as the largest single payout in competitive snowboarding.', 'tour-series', 'defunct', 'brand-run', 'global', NULL, 'multiple', NULL, ARRAY['halfpipe','slopestyle','quarterpipe','big-air','rail-jam']::text[], ARRAY['https://whitelines.com/archive/news/burton-global-open-series-08-09.html','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://experiencequeenstown.com/events/feature-events/burton-nz-open/','https://www.snowboarder.com/news/2010-burton-new-zealand-open-gears-up','https://whitelines.com/archive/news/mikkel-bang-jenny-jones-win-nissan-x-trail-nippon-open-parkstyle-finals.html']::text[], 'likely'),
  ('burton-new-zealand-open', 'Burton New Zealand Open', 'annual', 2003, 2011, 'The Southern Hemisphere opener of the Burton Global Open Series and, at its peak, the largest snowboard contest in New Zealand. Ran at Snow Park NZ near Wanaka and at Cardrona Alpine Resort, which held the country''s only 22-foot superpipe.', 'tour-stop', 'unconfirmed', 'brand-run', 'oceania', NULL, 'New Zealand', NULL, ARRAY['halfpipe','slopestyle','quarterpipe']::text[], ARRAY['https://info.scoop.co.nz/Burton_NZ_Open','https://www.snowboarder.com/news/2010-burton-new-zealand-open-gears-up','https://snowboardmag.com/stories/world-class-riders-arrive-wanaka-nz-2011-burton-new-zealand-open','https://experiencequeenstown.com/events/feature-events/burton-nz-open/']::text[], 'likely'),
  ('burton-rail-days', 'Burton Rail Days', 'annual', NULL, NULL, 'Burton''s urban street-snowboarding contest staged in central Tokyo, built from imported snow in the Roppongi Hills arena and run alongside a free public beginner park. The 2015 edition was reported as the fifth.', 'major-contest', 'unconfirmed', 'brand-run', 'japan', 'Roppongi Hills', 'Japan', NULL, ARRAY['rail-jam','jib']::text[], ARRAY['https://www.timeout.com/tokyo/things-to-do/burton-rail-days']::text[], 'likely'),
  ('canada-snowboard-junior-nationals', 'Canada Snowboard Junior National Championships', 'annual', NULL, NULL, 'Canada Snowboard''s week-long junior championship, run across Grom, Youth and JR FIS categories in six disciplines. The junior national title event feeding the Junior World Championships team.', 'national-championship', 'active', 'Canada Snowboard', 'north-america', NULL, 'Canada', NULL, ARRAY['slopestyle','banked-slalom','halfpipe','parallel-giant-slalom','boardercross','big-air']::text[], ARRAY['https://www.canadasnowboard.ca/en/events/nationalsjr/','https://www.canadasnowboard.ca/en/events/']::text[], 'verified'),
  ('canada-snowboard-national-championships', 'Canadian National Snowboard Championships', 'annual', NULL, NULL, 'Canada''s national snowboard titles, awarded by Canada Snowboard (the Canadian Snowboard Federation, founded 1991). Since at least the 2010s the championships have been split into separate freestyle, alpine, snowboardcross and para-snowboard events, each hosted at a different resort in the same season and each attached to the corresponding national tour (Air Nation for freestyle, Speed Nation for alpine/SBX/para). No single first year could be sourced.', 'national-championship', 'active', 'Canada Snowboard', 'north-america', NULL, 'Canada', ARRAY['Sport Chek Air Nation Freestyle Nationals','Sports Experts Speed Nation Nationals','Speed Nation Alpine Nationals','Speed Nation Snowboardcross Nationals']::text[], ARRAY['halfpipe','slopestyle','big-air','boardercross','parallel-giant-slalom','parallel-slalom','banked-slalom']::text[], ARRAY['https://www.canadasnowboard.ca/en/events/','https://www.canadasnowboard.ca/en/news/?id=1146','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259','https://en.wikipedia.org/wiki/Canadian_Snowboard_Federation']::text[], 'verified'),
  ('canada-winter-games-snowboarding', 'Snowboarding at the Canada Winter Games', 'annual', NULL, NULL, 'The snowboard programme of Canada''s biennial multi-sport games for young athletes, contested by provincial and territorial teams. The Games rotate host provinces; snowboarding has been staged at Mt Sima (Whitehorse 2007), Ski Martock (Halifax 2011), Prince George (2015), Canyon Ski Resort and WinSport Canada Olympic Park (Red Deer 2019) and Mark Arendz Provincial Ski Park at Brookvale (PEI 2023). The first year snowboarding appeared on the programme was not sourced.', 'national-championship', 'active', 'Canada Games Council', 'north-america', NULL, 'Canada', NULL, ARRAY['parallel-giant-slalom','halfpipe','boardercross','slopestyle']::text[], ARRAY['https://en.wikipedia.org/wiki/Snowboarding_at_the_2011_Canada_Winter_Games','https://en.wikipedia.org/wiki/2007_Canada_Winter_Games','https://en.wikipedia.org/wiki/2015_Canada_Winter_Games','https://en.wikipedia.org/wiki/2019_Canada_Winter_Games','https://en.wikipedia.org/wiki/2023_Canada_Winter_Games']::text[], 'verified'),
  ('circuito-bichos', 'Circuito Bichos', 'annual', NULL, NULL, 'Chile''s under-18 snowboard tour run by the national association Anden, in three age categories (Saltamontes, Grillos, Pulgas) across fun race/boardercross, downhill and slopestyle at the Santiago-area resorts. Anden also ran the professional Circuito RSS (Ranking Ski y Snowboard), a combined freestyle ranking for skiers and snowboarders.', 'grassroots-contest', 'unconfirmed', 'Anden (Chilean snowboard association, WSF member)', 'south-america', NULL, 'Chile', NULL, ARRAY['boardercross','slopestyle','downhill']::text[], ARRAY['https://www.worldsnowboardfederation.org/chile-snowboard-events-2009/']::text[], 'likely'),
  ('coors-light-saint-sauveur-mountain-challenge', 'Coors Light Saint-Sauveur Mountain Challenge', 'annual', 2010, NULL, 'Quebec event at Mont Saint-Sauveur which SnowboardQuebec''s provincial history records as starting in 2010. Format, disciplines and end date not sourced.', 'grassroots-contest', 'unconfirmed', 'brand-run', 'north-america', 'Mont Saint-Sauveur', 'Canada', NULL, ARRAY['other']::text[], ARRAY['https://www.snowboardquebec.com/histoire/']::text[], 'likely'),
  ('coupe-quebec-snowboard', 'Coupe Quebec (Quebec Snowboard Cup)', 'annual', NULL, NULL, 'Quebec''s provincial FIS-sanctioned circuit, listed on the SnowboardQuebec calendar as Coupe QC/FIS events. Host hills in the 2025-26 season include Val Saint-Come (rail jam, SBX), Belle-Neige (slopestyle, banked slalom, alpine) and Le Relais. Quebec''s provincial federation was founded in 1987 as the Federation de Surf des Neiges du Quebec.', 'grassroots-contest', 'active', 'Association quebecoise de snowboard', 'north-america', NULL, 'Canada', NULL, ARRAY['slopestyle','boardercross','rail-jam','parallel-giant-slalom','banked-slalom']::text[], ARRAY['https://www.snowboardquebec.com/calendrier/','https://www.snowboardquebec.com/histoire/']::text[], 'likely'),
  ('dirksen-derby', 'Dirksen Derby', 'annual', 2007, NULL, 'Hand-built parallel banked slalom race founded by pro snowboarder Josh Dirksen at Mt. Bachelor, Oregon, first run on December 1, 2007 as a fundraiser for Tyler Eklund, a local snowboarder paralysed in a contest earlier that year. It runs a Red (harder) and Green (friendlier) course with combined times, and includes snowboard, sit-ski and splitboard divisions. Beneficiaries have included Oregon Adaptive Sports, Protect Our Winters and the Central Oregon Avalanche Association; the organisers state more than $300,000 has been donated to non-profits and community members.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Mt. Bachelor', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://www.dirksenderby.com/Race/DirksenDerby/Page-10','https://bendmagazine.com/event/dirksen-derby-18-snowboard-rally-race/2025-12-21/','https://www.bendsource.com/outside/dirksen-derby-rally-race-returns-to-mt-bachelor-for-year-17-22369702/']::text[], 'verified'),
  ('european-world-snowboarding-championships', 'European World Snowboarding Championships', 'annual', 1987, NULL, 'The rival European world championships of January 1987, run at Livigno, Italy and St Moritz, Switzerland in the same season as the second Breckenridge Worlds. The split between the two claimed world titles is what pushed NASBA and the Snowboard European Association to negotiate a single World Cup circuit.', 'legacy-contest', 'unconfirmed', 'independent', 'europe', NULL, 'multiple', NULL, NULL, ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://www.carvers.it/storia-inglese/','https://snowboarding8090.com/history/']::text[], 'likely'),
  ('fis-snowboard-junior-world-championships', 'FIS Snowboard Junior World Championships', 'annual', 1997, NULL, 'Annual FIS age-group world championship, first held at Corno alle Scale (ITA) in February 1997. Single-venue through 2015; from 2016 onward routinely split across two to four venues in one season, and combined with freestyle skiing as the FIS Freestyle Ski and Snowboarding Junior World Championships. RESULTS ARCHIVE for a later pass: https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=YYYY&categorycode=WJC (note: the FIS category code is WJC, not JWC), each row linking to per-race pages at https://www.fis-ski.com/DB/general/results.html?sectorcode=SB&raceid=NNNNN.', 'major-contest', 'active', 'FIS', 'global', NULL, 'multiple', ARRAY['FIS Freestyle Ski and Snowboarding Junior World Championships']::text[], ARRAY['halfpipe','giant-slalom','parallel-slalom','parallel-giant-slalom','boardercross','big-air','slopestyle','team']::text[], ARRAY['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1997&categorycode=WJC','https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=2026&categorycode=WJC','https://en.wikipedia.org/wiki/FIS_Snowboarding_Junior_World_Championships']::text[], 'verified'),
  ('fis-snowboard-world-championships', 'FIS Snowboard World Championships', 'annual', 1996, NULL, 'FIS''s own world championship, first held at Lienz (AUT) in January 1996, two years after FIS took snowboarding under its jurisdiction and while the rival ISF was still running its own world championships. Held in odd-numbered years from 1999 onward (1996 and 1997 were run in consecutive years); skipped in Olympic years. Combined with the FIS Freestyle World Ski Championships from 2015. RESULTS ARCHIVE for a later pass: https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=YYYY&categorycode=WSC (seasoncode = calendar year the championships were held); each event row links to per-race pages at https://www.fis-ski.com/DB/general/results.html?sectorcode=SB&raceid=NNNNN (verified example raceid=22567, 2025 mixed parallel team).', 'major-contest', 'active', 'FIS', 'global', NULL, 'multiple', ARRAY['FIS Snowboarding World Championships']::text[], ARRAY['halfpipe','giant-slalom','slalom','parallel-slalom','parallel-giant-slalom','boardercross','big-air','slopestyle','team']::text[], ARRAY['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1996&categorycode=WSC','https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=2025&categorycode=WSC','https://en.wikipedia.org/wiki/FIS_Snowboard_World_Championships']::text[], 'verified'),
  ('fis-snowboard-world-cup', 'FIS Snowboard World Cup', 'tour', 1994, NULL, 'FIS''s season-long snowboard tour. The FIS results database holds no World Cup events before the 1994/95 season; the first World Cup stop on record is Zell am See/Kaprun (AUT), 24-26 November 1994. Edition rows here are SEASONS, keyed to the season end year, not individual stops. RESULTS ARCHIVE for a later pass: season calendars at https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=YYYY&categorycode=WC ; per-race results at https://www.fis-ski.com/DB/general/results.html?sectorcode=SB&raceid=NNNNN ; season Crystal Globe / cup standings at https://www.fis-ski.com/DB/general/cup-standings.html?sectorcode=SB&seasoncode=YYYY&cupcode=WC&disciplinecode=ALL&gendercode=M (or gendercode=L) - all three patterns verified.', 'tour-series', 'active', 'FIS', 'global', NULL, 'multiple', NULL, ARRAY['halfpipe','giant-slalom','slalom','parallel-slalom','parallel-giant-slalom','boardercross','big-air','slopestyle','team']::text[], ARRAY['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1994&categorycode=WC','https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1995&categorycode=WC','https://www.fis-ski.com/DB/general/cup-standings.html?sectorcode=SB&seasoncode=2026&cupcode=WC&disciplinecode=ALL&gendercode=M']::text[], 'verified'),
  ('focus-banked-slalom', 'Focus Banked Slalom', 'annual', NULL, NULL, 'Midwest banked slalom at Tyrol Basin, Wisconsin. Local Freshies describes the March 1, 2026 edition as ''now in its 19th year''.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Tyrol Basin', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('freestyle-ch', 'freestyle.ch', 'annual', 1995, NULL, 'Urban big air staged on the Landiwiese on Lake Zurich each September, part of a four-discipline freestyle festival (snowboard, freeski, FMX, skate) drawing around 100,000 spectators. Began in 1995 as Nescafe Zueri Inline; admission became paid in 2005.', 'major-contest', 'unconfirmed', 'independent', 'europe', 'Landiwiese, Zurich', 'Switzerland', ARRAY['Nescafe Zueri Inline']::text[], ARRAY['big-air']::text[], ARRAY['https://de.wikipedia.org/wiki/Freestyle.ch']::text[], 'likely'),
  ('gravity-games-winter', 'Winter Gravity Games', 'annual', 2000, 2000, 'Winter edition of the NBC/Octagon-backed Gravity Games, staged once at Mammoth Mountain, California in 2000 as a broadcast rival to Winter X Games. Not repeated.', 'major-contest', 'defunct', 'independent', 'north-america', 'Mammoth Mountain', 'USA', NULL, ARRAY['superpipe','big-air','boardercross']::text[], ARRAY['https://en.wikipedia.org/wiki/Gravity_Games']::text[], 'likely'),
  ('halo-halo-timberline', 'Halo-Halo', 'annual', 2023, NULL, 'BIPOC-focused summer snowboard gathering on the Palmer snowfield at Timberline, Mt. Hood, Oregon, started in 2023. The 2026 edition is listed for July 10-12. Whether it is judged as a contest or run as a session was not confirmed in this pass.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Timberline Lodge and Ski Area', 'USA', NULL, NULL, ARRAY['https://www.snowboard.international/features/north-america-snowboard-events-2025-26/']::text[], 'likely'),
  ('holy-oly-revival', 'Holy Oly Revival', 'annual', 2004, NULL, 'A Snowboy Productions grassroots contest at The Summit at Snoqualmie, Washington, built around a quarterpipe and a jib playground (''Tube City'') beneath the Olympia beer can water tower at Summit East. It is a quarterpipe and jib jam, not a banked slalom. Winners received cases of Olympia beer. The Snowboarder''s Journal describes the quarterpipe events as running about eight years.', 'grassroots-contest', 'dormant', 'independent', 'north-america', 'The Summit at Snoqualmie', 'USA', NULL, ARRAY['quarterpipe','jib','rail-jam']::text[], ARRAY['https://www.snowboarder.com/news/7th-annual-holy-oly-the-olympic-hangover-cure','https://www.lib-tech.com/blog/2007/02/14/holy-crap-it%E2%80%99s-the-fourth-annual-holy-oly-revival/','https://thesnowboardersjournal.com/blogs/exclusives/twenty-years-snowboy-productions','https://www.gnu.com/blog/2010/02/24/holy-oly-you-can%E2%80%99t-spell-olympics-without-oly/','http://thesummitcrew.blogspot.com/p/history-of-summit.html']::text[], 'likely'),
  ('hot-dawgz-and-hand-rails', 'Hot Dawgz & Hand Rails', 'annual', 2004, NULL, 'Southern California''s pre-season rail jam, run at Bear Mountain (later Snow Summit) in Big Bear Lake, California, on trucked-in man-made snow in September - traditionally the first major rail contest of the North American season. Jam format on urban-style features. First held in 2004; the 2012 edition was the ninth annual and used 130 tons of snow for about 40 pro riders.', 'grassroots-contest', 'dormant', 'brand-run', 'north-america', 'Bear Mountain', 'USA', NULL, ARRAY['rail-jam','jib']::text[], ARRAY['https://www.firsttracksonline.com/2012/09/07/hot-dawgz-and-hand-rails-pre-season-rail-jam-returns-to-bear-mountain/','https://localfreshies.com/event/hot-dawgz-and-hand-rails-2019-big-bear/']::text[], 'likely'),
  ('isf-snowboard-world-championships', 'ISF World Championships', 'annual', 1993, NULL, 'The snowboarders'' own world championship, run by the International Snowboard Federation (founded 1989 as the ISA, renamed ISF 1991) and held for the first time at Ischgl, Austria in 1993. From 1996 the ISF and FIS ran rival world championships in the same seasons; the split drove Terje Haakonsen''s boycott of the 1998 Nagano Olympic qualification, since the IOC gave FIS rather than the ISF control of Olympic snowboarding. The ISF filed for bankruptcy in Innsbruck and ceased operating on 22 June 2002, ending the rival championship. NO CENTRAL RESULTS ARCHIVE FOUND - see open_questions.', 'major-contest', 'defunct', 'ISF (International Snowboard Federation)', 'global', NULL, 'multiple', NULL, ARRAY['halfpipe','giant-slalom','slalom','boardercross']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://en.wikipedia.org/wiki/International_Snowboard_Federation','https://de.wikipedia.org/wiki/International_Snowboarding_Federation','https://en.wikipedia.org/wiki/Terje_H%C3%A5konsen']::text[], 'likely'),
  ('isf-world-championships', 'ISF Snowboard World Championships', 'annual', 1993, 1999, 'The world championship of the International Snowboard Federation, the riders'' governing body of the 1990s. German Wikipedia states four ISF world championships were held between 1993 and 1999. The ISF''s own successor (WSF) dates the federation''s founding to 1990, when five nations and 120 racers formed it; English Wikipedia instead dates it to 1989 in Vancouver as the International Snowboard Association, renamed ISF in 1991. The ISF ceased operations on 22 June 2002.', 'major-contest', 'defunct', 'ISF', 'global', NULL, 'multiple', NULL, ARRAY['halfpipe','giant-slalom','slalom','parallel-slalom','boardercross','other']::text[], ARRAY['https://de.wikipedia.org/wiki/Snowboard-Weltmeisterschaft','https://en.wikipedia.org/wiki/International_Snowboard_Federation','https://www.worldsnowboardfederation.org/inside-wsf/history/','https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://www.carvers.it/storia-inglese/']::text[], 'likely'),
  ('isf-world-snowboarding-championships', 'ISF World Snowboarding Championships', 'annual', 1993, NULL, 'The rider-run International Snowboard Federation''s world championship, and the counterweight to the FIS world championships of the 1990s. The first was held at Ischgl, Austria in 1993. By 1999/2000 the title was contested across a season-long Motorola ISF World Pro Tour rather than a single meeting. The ISF was dissolved in 2002.', 'major-contest', 'defunct', 'ISF (International Snowboard Federation)', 'global', NULL, 'multiple', ARRAY['Motorola ISF World Championships']::text[], ARRAY['halfpipe','boardercross','other']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://www.sportcal.com/pressreleases/the-motorola-isf-world-championships-1999-2000-halfpipe-davos-sui/','https://de.wikipedia.org/wiki/Snowboard-Weltmeisterschaften']::text[], 'likely'),
  ('jla-mammoth-banked-slalom', 'JLA Mammoth Banked Slalom', 'annual', NULL, NULL, 'Banked slalom at Mammoth Mountain honouring the legacy of pro snowboarder Jeff Anderson (JLA). Local Freshies notes it celebrated its 10th anniversary in 2013 and lists the 2026 edition for February 27-March 1.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Mammoth Mountain', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('jsba-all-japan-snowboard-championships', 'JSBA All Japan Snowboard Championships', 'annual', 1983, NULL, 'Japan''s national amateur snowboard championship, run by the JSBA and reached through regional and G1 qualifying events. The 41st edition in 2023 is described on the JSBA site as annual since 1983; the JSBA''s own history page states the first All Japan championship was staged in 1982 at Kyowa Ski Resort, Akita, with the previous year''s North American champion invited. Programme covers halfpipe, slopestyle, snowboard cross, straight jump (big air), giant slalom and dual slalom; venues rotate and a single edition often splits across two resorts.', 'national-championship', 'active', 'JSBA (Japan Snowboarding Association)', 'japan', NULL, 'Japan', ARRAY['JSBA全日本スノーボード選手権大会']::text[], ARRAY['halfpipe','slopestyle','boardercross','big-air','giant-slalom','dual-slalom']::text[], ARRAY['https://www.jsba.or.jp/information/history/','https://www.jsba.or.jp/ajsc_site/ajsc41/','https://www.jsba.or.jp/ajsc_site/ajsc43/']::text[], 'likely'),
  ('jsba-all-japan-snowboard-technical-championships', 'JSBA All Japan Snowboard Technical Championships', 'annual', NULL, NULL, 'JSBA championship judging overall riding ability rather than tricks or times, in Alpine and Freestyle categories for men and women plus a club team competition. Regional qualifiers run three events, the national final five. The 33rd edition was held in the 2025/26 season.', 'national-championship', 'active', 'JSBA (Japan Snowboarding Association)', 'japan', NULL, 'Japan', ARRAY['JSBA全日本スノーボードテクニカル選手権大会']::text[], ARRAY['other']::text[], ARRAY['https://www.jsba.or.jp/education/ajstc/','https://www.jsba.or.jp/ajstc_site/ajstc33/']::text[], 'likely'),
  ('kaunertal-opening', 'Kaunertal Opening', 'annual', 1986, NULL, 'Glacier season-opening snowboard gathering in the Tirol, combining a rider contest with a brand testival, mini-ramp and jib sessions. Onboard and World Snowboard Guide both call the 2015 edition the 30th and Whitelines calls 2022 the 37th year, which places the first edition in 1986. The 2015 edition revived the mini-ramp after a 15-year absence and ran a Legends Invitational session.', 'legacy-contest', 'active', 'independent', 'europe', 'Snowpark Kaunertal, Kaunertaler Gletscher', 'Austria', ARRAY['KTO']::text[], ARRAY['jib','rail-jam','other']::text[], ARRAY['https://onboardmag.com/news/snowboarding-events/30th-kaunertal-opening-event-recap.html','https://www.worldsnowboardguide.com/news/30th-kaunertal-opening-2015.html','https://whitelines.com/snowboard-culture/snowboard-events/kto-2022-kaunertal-opening-is-back.html']::text[], 'likely'),
  ('king-of-the-mountain-ski-cooper', 'King of the Mountain (Ski Cooper)', 'annual', 1981, NULL, 'Widely cited as the first modern snowboard contest, held in April 1981 at Ski Cooper, Leadville, Colorado, at a time when almost no resort would host snowboarders. Tom Sims and Jake Burton Carpenter both attended.', 'legacy-contest', 'unconfirmed', 'independent', 'north-america', 'Ski Cooper', 'USA', NULL, ARRAY['slalom','other']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://en.wikipedia.org/wiki/Snowboarding']::text[], 'likely'),
  ('laax-open', 'LAAX OPEN', 'annual', 2016, NULL, 'Direct successor to the Burton European Open at the same resort. Launched for winter 2016 after Burton stepped back from the BEO, keeping the open-entry format, the core organising team and the Laax superpipe. It joined the FIS Snowboard World Cup in its second year and now also runs a freeski slopestyle World Cup alongside the snowboard events.', 'major-contest', 'active', 'FIS', 'europe', 'LAAX', 'Switzerland', NULL, ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://onboardmag.com/news/european-news/laax-set-to-host-laax-open-2016.html','https://www.burton.com/blogs/the-burton-blog/10-years-laax-open/','https://laaxopen.com/en/hall-of-fame/','https://laaxopen.com/en/about-laax-open/']::text[], 'verified'),
  ('mt-baker-last-stand-rail-jam', 'Last Stand Rail Jam', 'annual', NULL, NULL, 'End-of-season freestyle contest at Mt. Baker Ski Area, listed by the ski area as open to all skill levels. Scheduled for Saturday, April 3, 2027 in the 2026-27 season.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Mt. Baker Ski Area', 'USA', NULL, ARRAY['rail-jam']::text[], ARRAY['https://www.mtbaker.us/events/']::text[], 'likely'),
  ('mt-baker-ravens-edge-dual-slalom', 'Raven''s Edge Dual Slalom', 'annual', NULL, NULL, 'Two-day ski and snowboard dual slalom at Mt. Baker Ski Area, open to all ages and abilities. Scheduled for April 10-11, 2027 in the 2026-27 season.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Mt. Baker Ski Area', 'USA', NULL, ARRAY['dual-slalom']::text[], ARRAY['https://www.mtbaker.us/events/']::text[], 'likely'),
  ('mt-baker-timbrrr-best-trick', 'TIMBRRR! Best Trick Contest', 'annual', NULL, NULL, 'Early-season best-trick contest run in Mt. Baker''s wooden-feature zone, The Sticks. Scheduled for Saturday, December 12, 2026 in the 2026-27 season.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Mt. Baker Ski Area', 'USA', NULL, ARRAY['jib']::text[], ARRAY['https://www.mtbaker.us/events/']::text[], 'likely'),
  ('mt-spokane-banked-slalom', 'Mt. Spokane Banked Slalom', 'annual', NULL, NULL, 'Banked slalom on a hand-built course at Mt. Spokane, Washington, run by the non-profit ski area. Two timed runs, best run counts; open to both snowboarders and skiers with Pro/Open and amateur age divisions. The 2025 edition was held March 8.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Mt. Spokane Ski & Snowboard Park', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://www.mtspokane.com/bankedslalom']::text[], 'likely'),
  ('nate-chute-banked-slalom', 'Nate Chute Banked Slalom', 'annual', NULL, NULL, 'Banked slalom at Whitefish Mountain Resort, Montana, associated with the Nate Chute Foundation. Local Freshies calls it the ''second longest running Banked Slalom in the US''; the same page also calls the Neil Edgeworth Memorial at Big White the ''second oldest'', so the claim needs checking. The 2026 edition is listed for March 14-15.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Whitefish Mountain Resort', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('national-collegiate-snowboarding-championships', 'National Collegiate Snowboarding Championships', 'annual', 1989, NULL, 'First collegiate snowboard championship in the United States, held at Stratton Mountain, Vermont in December 1989.', 'national-championship', 'unconfirmed', NULL, 'north-america', NULL, 'USA', NULL, NULL, ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[], 'likely'),
  ('national-snurfing-championships', 'National Snurfing Championships', 'annual', 1968, 1984, 'The Snurfer contests at Muskegon, Michigan are the direct ancestor of snowboard competition. The Michigan Snowboard Museum timeline dates the first World Snurfing Championship to 19 February 1968 at Blockhouse Hill in Muskegon State Park. The series ran at Blockhouse Hill through 1979 and then at Pando, and it is the event Jake Burton Carpenter entered in 1979 with a bindinged board, which prompted a separate open division.', 'legacy-contest', 'defunct', NULL, 'north-america', NULL, 'USA', ARRAY['World Snurfing Championship','National Snurf Championship','National Snurfer Championship','National Snow Surfing Championship']::text[], ARRAY['downhill','slalom','other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html','https://en.wikipedia.org/wiki/Snowboarding']::text[], 'likely'),
  ('neil-edgeworth-memorial-banked-slalom', 'Neil Edgeworth Memorial Banked Slalom', 'annual', 1987, NULL, 'Big White''s banked slalom, first run in the 1987/88 season as the Inland Snowboard Big White Banked Slalom and renamed after local rider Neil Edgeworth, who was killed by an avalanche in France in 1997. Run in a natural gully beside the Ridge Rocket chair and later at TELUS Park, with pro, amateur (age groups from 11-and-under to 60+) and para divisions on the same course. Now organised with BC Snowboard; the organisers describe it as a gathering rather than a competition. 320 entrants in 2017, 255 in 2025.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Big White Ski Resort', 'Canada', ARRAY['Inland Snowboard Big White Banked Slalom']::text[], ARRAY['banked-slalom']::text[], ARRAY['https://www.bigwhite.com/explore-big-white/blog/mountain-news/nebs-26yrs-tradition','https://www.bigwhite.com/explore-big-white/blog/telus-park/big-white-hosts-20th-annual-neil-edgeworth-banked-slalom','https://www.bigwhite.com/explore-big-white/blog/telus-park/25-years-nebs','https://www.bcsnowboard.com/wp-content/uploads/2026-27th-Annual-NEBS-Event-Information.March-20-22-2026.pdf']::text[], 'verified'),
  ('nescafe-champs-leysin', 'NESCAFE Champs', 'annual', 1991, NULL, 'Described by the World Snowboard Federation and World Snowboard Guide as the oldest snowboard event in Europe. First held in 1991 at Leysin; Nescafe was title sponsor 1994-2006 and returned in 2010. The contest spent three seasons in Valais before returning to Leysin in 2010 and reached its 20th edition in 2011. Later editions ran a hybrid slopestyle course combining a halfpipe with kickers, rails and a wallride.', 'legacy-contest', 'unconfirmed', 'independent', 'europe', 'Leysin', 'Switzerland', ARRAY['Nescafe Open Champs','Champs Open Leysin','Nokia Champs','The Champs','Nescafé Champs']::text[], ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/nescafe-open-champs-in-leysin-2010-the-oldest-european-snowboard-event/','https://www.worldsnowboardguide.com/news/cilka-sadar---lucien-koch-win-2011-champ-in-leysin.html','https://snowboarding.transworld.net/news/get-ready-for-the-nescafe-champs-in-leysin-switzerland-march-6-10/']::text[], 'verified'),
  ('nippon-open', 'Nissan X-Trail Nippon Open', 'annual', NULL, NULL, 'The Japanese stop of the Burton Global Open Series, held at ALTS Bandai in Fukushima Prefecture and reported at the time as one of Japan''s most popular snowboard events, drawing over 40,000 spectators. Winners took 8,000 points toward the Burton Global Open Series championship.', 'tour-stop', 'unconfirmed', 'brand-run', 'japan', 'ALTS Bandai', 'Japan', NULL, ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://whitelines.com/archive/news/japan-beckons-riders-for-5-star-nissan-x-trail-nippon-open.html','https://whitelines.com/archive/news/mikkel-bang-jenny-jones-win-nissan-x-trail-nippon-open-parkstyle-finals.html','https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[], 'likely'),
  ('niseko-moiwa-banked-slalom', 'Niseko Moiwa Banked Slalom', 'annual', NULL, NULL, 'Late-March banked slalom at Niseko Moiwa in Hokkaido, run across five divisions including snowskate and ski classes and a snowboard masters category for riders 43 and over.', 'grassroots-contest', 'active', 'independent', 'japan', 'Niseko Moiwa Ski Resort', 'Japan', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://niseko-moiwa.jp/ja/news/2025/03/10/532/']::text[], 'verified'),
  ('north-alps-banked-slalom', 'North Alps Banked Slalom', 'tour', NULL, NULL, 'Described as Japan''s only banked slalom series: three races in the Hakuba valley, Nagano, at Hakuba Iwatake, Tsugaike Mountain Resort and Hakuba Happo-one. The Tsugaike round (BANKED SLALOM TGK) is the second race and by 2026 had grown to two days with 260 riders a day and ski, snowboard, snowbike and parent-child divisions.', 'tour-series', 'active', 'independent', 'japan', NULL, 'Japan', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://steep.jp/en/custom/tsugaike-banked-slalom/']::text[], 'likely'),
  ('north-american-snowboarding-championships', 'North American Snowboarding Championships', 'annual', NULL, NULL, 'An early continental championship run in western Canada in the mid-to-late 1980s. TransWorld SNOWboarding''s first issue (fall 1987) covered a North American Championships at Banff; a snowboarding history project places a 1985 North American Championships at Calgary. Whether these are the same series is not established.', 'legacy-contest', 'unconfirmed', NULL, 'north-america', NULL, 'Canada', NULL, NULL, ARRAY['https://www.snowboarder.com/transworld-snowboarding-archive/three-decades-transworld-snowboarding-part-1-1987-1996','https://snowboarding8090.com/history/']::text[], 'likely'),
  ('norwegian-snowboard-championships', 'Norwegian Snowboard Championships', 'annual', NULL, NULL, 'Norway''s national snowboard titles, contested across several venues in a season and, in the TTR era, carrying 3-Star ranking status. The winner of the combined title receives the King''s Cup (Kongepokal). The 2010/11 Norwegian season carried 15 TTR/WSF 1-3 Star events in big air, slopestyle and halfpipe.', 'national-championship', 'unconfirmed', NULL, 'europe', NULL, 'Norway', ARRAY['NM i snowboard']::text[], ARRAY['halfpipe','slopestyle','big-air','boardercross']::text[], ARRAY['https://www.worldsnowboardfederation.org/the-3star-ttr-norwegian-championships/']::text[], 'likely'),
  ('nz-snowboard-nationals', 'New Zealand Snowboard Nationals', 'annual', NULL, NULL, 'New Zealand''s national snowboard titles, run by Snow Sports NZ as the culmination of a season-long National Park and Pipe series of sanctioned events. Cardrona Alpine Resort hosts the Cardrona NZ Freeski and Snowboard Junior Nationals annually and is naming sponsor of the national Park and Pipe team.', 'national-championship', 'unconfirmed', 'Snow Sports NZ', 'oceania', NULL, 'New Zealand', NULL, ARRAY['halfpipe','slopestyle','big-air','boardercross','other']::text[], ARRAY['https://www.sporty.co.nz/snowsportsnz/sports/snowboarding']::text[], 'likely'),
  ('oakley-girl-sessions-ruka', 'Oakley Girl Sessions', 'annual', 2004, NULL, 'Women-only snowboard event at Ruka in Finnish Lapland, run as a Swatch TTR 3-Star alongside open-ability sessions, a team contest and a freeski slopestyle. The 2010 edition was the seventh, placing the first around 2004. Enni Rukajarvi won the 2009 edition before her international breakthrough.', 'tour-stop', 'unconfirmed', 'independent', 'europe', 'Ruka BatteryPark, Ruka', 'Finland', ARRAY['Oakley Girlsessions']::text[], ARRAY['slopestyle','halfpipe','team']::text[], ARRAY['https://www.worldsnowboardfederation.org/7th-edition-of-oakley-girlsessions-at-ruka-finland-8-11-4-2010/']::text[], 'likely'),
  ('olympic-snowboarding', 'Snowboarding at the Olympic Winter Games', 'annual', 1998, NULL, 'Snowboarding was admitted to the Olympic programme for the 1998 Nagano Winter Games with men''s and women''s giant slalom and halfpipe. The programme has grown to 11 medal events by 2022 and 2026. RESULTS ARCHIVE for a later pass: Olympedia gives a complete per-Games event index at https://www.olympedia.org/editions/{edition_id}/sports/SBD (verified edition ids: 46=1998, 47=2002, 49=2006, 57=2010, 58=2014, 60=2018, 62=2022, 72=2026, 70=2020 Winter YOG, 73=2024 Winter YOG); each event on that index links to a full finishing-order page.', 'major-contest', 'active', 'IOC (sport governed at the Games by FIS)', 'global', NULL, 'multiple', NULL, ARRAY['halfpipe','giant-slalom','parallel-giant-slalom','parallel-slalom','boardercross','slopestyle','big-air','team']::text[], ARRAY['https://www.olympedia.org/sports/SBD','https://www.olympedia.org/editions/46/sports/SBD','https://www.olympedia.org/editions/72/sports/SBD']::text[], 'verified'),
  ('oneill-evolution', 'O''Neill Evolution', 'annual', 2006, 2013, 'Brand-run TTR contest at Davos, launched in 2006 and held every year for eight years to 2013 before O''Neill withdrew from major events. It carried 6Star status and was one of the first top-tier events to run women''s and men''s fields in both halfpipe and slopestyle (2011). It ran a week-long format in early January, closing with a big air or halfpipe final at the Bolgen slope below the Jakobshorn.', 'major-contest', 'defunct', 'TTR', 'europe', 'Davos', 'Switzerland', NULL, ARRAY['halfpipe','slopestyle','big-air']::text[], ARRAY['https://www.worldsnowboardguide.com/news/no-o-neill-evolution-in-davos-this-season.html','https://www.boardshop.de/boardmag/snowboard/news/oneill-evolution-2011-in-davos-vom-2-bis-8-januar_aid_16198.html','https://www.boardshop.de/boardmag/snowboard/news/ttr-6star-contest-oneill-evolution-in-davos-live-webcast-04-09-01-2010_aid_16337.html','https://www.worldsnowboardguide.com/events/o-neill-evolution-2013.html','https://whitelines.com/events/oneill-evolution']::text[], 'verified'),
  ('ontario-snowboard-provincial-series', 'Ontario Snowboard Provincial Series', 'annual', NULL, NULL, 'Ontario''s provincial series across freestyle and alpine disciplines, run by Ontario Snowboard (the Association of Ontario Snowboarders, based in Collingwood). Host clubs and resorts include Alpine Ski Club, Horseshoe Valley Resort, Beaver Valley and Craigleith Ski Club. Ontario Snowboard also delivers the snowboard programme for the 2027 Canada Winter Games.', 'grassroots-contest', 'active', 'Ontario Snowboard', 'north-america', NULL, 'Canada', NULL, ARRAY['halfpipe','slopestyle','big-air','giant-slalom','parallel-giant-slalom']::text[], ARRAY['https://www.ontariosnowboard.ca/']::text[], 'verified'),
  ('op-pro-snowboarding', 'OP Pro of Snowboarding', 'annual', NULL, NULL, 'Ocean Pacific''s snowboard contest, one of the surf-brand events that carried prize money into snowboarding in the late 1980s. The Snowboarder/TransWorld 1980s timeline records an OP Pro of Snowboarding at June Mountain, California in 1989.', 'legacy-contest', 'defunct', 'brand-run', 'north-america', NULL, 'USA', NULL, ARRAY['halfpipe','giant-slalom']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[], 'likely'),
  ('op-wintersurf', 'OP Wintersurf', 'annual', 1991, NULL, 'Ocean Pacific''s combined surf-and-snowboard contest, run as a surf event at Huntington Beach and a snowboard obstacle course at Bear Mountain in the same competition.', 'legacy-contest', 'defunct', 'brand-run', 'north-america', NULL, 'USA', NULL, ARRAY['other']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s']::text[], 'likely'),
  ('pacwest-banked-slalom', 'PacWest Banked Slalom', 'annual', 2022, NULL, 'Banked slalom created in 2022 by Marcel Dolak at Summit East, the former PacWest ski area at Snoqualmie Pass, Washington - a venue that hosted Northwest snowboard contests and jams through the 1980s to 2000s (the Good and Plenty Jam, Urban Circus Jumpfest) and where Craig Kelly and Jamie Lynn rode. The 2026 edition offered 21 divisions from ages 6 to 60+.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Summit East, The Summit at Snoqualmie', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://www.summitatsnoqualmie.com/events/pacwest-banked-slalom','https://thesnowboardersjournal.com/blogs/exclusives/pacwest-banked-slalom-2022','https://thesnowboardersjournal.com/blogs/exclusives/pacwest-banked-slalom-2024']::text[], 'verified'),
  ('pleasure-jam', 'Pleasure Jam', 'annual', 2003, NULL, 'European season-opening slopestyle contest on the Dachstein glacier, run by QParks (which has managed the Superpark since 2004) as the first stop of the QParks Snowboard Tour and, in TTR years, a Swatch TTR 4-Star. The 2015 edition was billed as Vol. 13, which places the first edition in 2003.', 'major-contest', 'unconfirmed', 'independent', 'europe', 'Superpark Dachstein, Dachstein Glacier', 'Austria', ARRAY['Horsefeathers Pleasure Jam','O''Neill Pleasure Jam']::text[], ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/pleasure-jam-vol-13-postponed/','https://www.worldsnowboardfederation.org/horsefeather-pleasure-jam-09-in-dachstain/','https://www.worldsnowboardfederation.org/qparks-snowboard-tour-set-for-201617/']::text[], 'likely'),
  ('qparks-snowboard-tour', 'QParks Snowboard Tour', 'tour', 2009, NULL, 'Amateur freestyle snowboard tour across QParks-built parks in Austria, Germany, Italy and Switzerland, with professional judging and a shared prize pot (EUR 40,000 in 2016/17). The 2016/17 season was described as its seventh, placing the first season around 2009/10. It opens each year with the Pleasure Jam on the Dachstein.', 'tour-series', 'unconfirmed', 'independent (QParks)', 'europe', NULL, 'multiple', NULL, ARRAY['slopestyle','rail-jam','jib']::text[], ARRAY['https://www.worldsnowboardfederation.org/qparks-snowboard-tour-set-for-201617/']::text[], 'likely'),
  ('rattlesnake-banked-slalom', 'Rattlesnake Banked Slalom', 'annual', 2023, NULL, 'Snowboard-only banked slalom at Buck Hill, Minnesota - the Twin Cities hill where Lindsey Vonn learned to race. Fastest of two runs, six divisions (Junior 15 and under, Open 16-39, Master 40+, each split by gender), each capped at 25 riders. The March 2, 2025 edition was the third annual.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Buck Hill', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://buckhill.com/events/rattlesnake-banked-slalom-2025/']::text[], 'likely'),
  ('rey-del-park', 'Rey del Park', 'annual', NULL, NULL, 'Described by the World Snowboard Federation as the biggest freestyle event in Chile, held in the terrain park at El Colorado above Santiago and open to skiers as well as snowboarders. The 2012 running was the eighth edition, which places the first around 2005, and was the first year it counted towards the WSF South America Tour.', 'major-contest', 'unconfirmed', 'independent', 'south-america', 'El Colorado', 'Chile', ARRAY['Lippi Rey del Park','King of the Park']::text[], ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/viii-rey-del-park-el-colorado-chile/','https://www.worldsnowboardfederation.org/lippi-king-of-the-park-in-el-colorado-chile/']::text[], 'likely'),
  ('roxy-chicken-jam', 'Roxy Chicken Jam', 'annual', NULL, NULL, 'All-female contest run by Roxy, described as the only women''s-only events to hold Swatch TTR 6Star accreditation. It ran a European stop in December and a US stop in late March; the US final was the season-defining event for the TTR women''s ranking, with the women''s TTR world champion decided there. Wikipedia dates the event to the 2004-05 season.', 'major-contest', 'defunct', 'TTR', 'global', NULL, 'multiple', ARRAY['Chicken Jam']::text[], ARRAY['halfpipe','slopestyle','big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/Chicken_Jam','https://www.worldsnowboardfederation.org/ttr-women-tour-announced/','https://coolerlifestyle.com/news/everything-you-wanted-to-know-about-the-ttr-but-were-afraid-to-ask.html']::text[], 'likely'),
  ('shakedown-snowboard-games', 'Shakedown', 'annual', 2002, 2015, 'Founded in 2002 by Brendan O''Dowd and Patryck Bernier at Mont Saint-Sauveur in the Laurentians, explicitly to fill the gap left by the end of the WestBeach Classic. Jam format scored 50/50 between big air and street/rail, with riders calling tricks in advance and no repeats. 6,000 spectators and a $10,000 winner-take-all purse in year one, later 25,000 spectators and $50,000 across the top ten; broadcast on TSN, RDS and TVA Sports. Seb Toutant won the pro category here in 2006 at age 13. Empire was title sponsor 2002-2008, Ride Snowboards from 2009, under which the event expanded to the USA (2010) and Europe (2011).', 'major-contest', 'defunct', 'independent', 'north-america', 'Mont Saint-Sauveur', 'Canada', ARRAY['Empire Shakedown','Ride Shakedown','The Original Snowboard Games']::text[], ARRAY['slopestyle','big-air','rail-jam','jib']::text[], ARRAY['https://en.wikipedia.org/wiki/Shakedown_(Snowboard_Games)','https://kingsnowboard.com/blogs/uncategorized/timepiece-shakedown','https://www.snowboardquebec.com/histoire/']::text[], 'verified'),
  ('showcase-showdown', 'Showcase Showdown', 'annual', 1997, NULL, 'Shop contest started by Showcase Snowboards in Whistler Village (opened 1989 as Showcase Tennis, later the largest Burton dealer in North America) and billed as Canada''s longest-running snowboard competition. Held on Blackcomb; by the 2010s a big air with a $10,000 pro men''s purse plus a berth in the WSSF Monster Energy Shred Show, with a junior rail jam added in 2015.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Whistler Blackcomb', 'Canada', NULL, ARRAY['big-air','halfpipe','rail-jam']::text[], ARRAY['https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx','https://snowboardmag.com/news/whistler-blackcombs-18th-annual-showcase-showdown-returns-march-14','https://whistlermuseum.org/2023/03/07/selling-snowboards/','https://www.straight.com/life/402596/showcase-showdown-and-whistler-ski-and-snowboard-fest-go-far-beyond-rock-n-snow']::text[], 'likely'),
  ('sidesurfers-banked-slalom', 'Sidesurfers Banked Slalom', 'annual', NULL, NULL, 'Vermont banked slalom at Sugarbush. The 2026 edition is listed for March 21.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Sugarbush Resort', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('slash-the-mass-banked-slalom', 'Slash the Mass Banked Slalom', 'annual', NULL, NULL, 'Snowboard-only banked slalom at Snowmass, Colorado, run by Aspen Snowmass with age divisions from 12-and-under to 40-plus plus Open/Pro men and women. The edition listed on the resort''s site is billed as the 12th annual and was cancelled for snow conditions; the year of that edition is not stated on the page.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Snowmass', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://www.aspensnowmass.com/visit/events/slash-the-mass-banked-slalom']::text[], 'likely'),
  ('snoboard-shop-north-american-championships', 'The Snoboard Shop North American Snowboarding Championships', 'annual', 1985, 1988, 'The first Canadian snowboard contest of any scale, run by Ken Achenbach out of The Snoboard Shop in Calgary - the world''s first snowboard-only shop. Held on the May long weekend at Sunshine Village in Banff with a $20,000 purse, it was one of the most important early North American contests; a photo of Dave Achenbach from the event ran on the cover of the first issue of TransWorld Snowboarding. Sunshine pulled out mid-season in 1988 and Mt Norquay took the event over, putting Norquay on the TransWorld cover. Disciplines run each year were not sourced.', 'legacy-contest', 'defunct', 'independent', 'north-america', NULL, 'Canada', ARRAY['North American Snowboarding Championships']::text[], ARRAY['other']::text[], ARRAY['https://www.snowboardquebec.com/histoire/','https://kootenaymountainculture.com/meet-the-men-who-brought-snowboarding-to-canada/','https://banffnorquay.com/blog/lift-lines-humans-of-norquay-a-hill-makes-space-for-snowboarding/','https://www.snowboarder.com/snowboarders/fathers-of-snowboarding-ken-achenbach']::text[], 'likely'),
  ('snowboard-jamboree', 'Snowboard Jamboree', 'annual', 2006, NULL, 'Quebec''s flagship freestyle snowboard festival, produced by Gestev and split between Stoneham Mountain Resort and a downtown Quebec City big air site (Ilot Fleurie). It carried FIS Snowboard World Cups and, from 2014, 5-star World Snowboard Tour status; the 2014 edition was billed as the 9th Jamboree and the 15th World Cup held in Quebec. It hosted the 2013 FIS Snowboarding World Championships and moved to an all-urban big air format in 2016. Whether it has run since 2019 was not established.', 'major-contest', 'unconfirmed', 'FIS', 'north-america', NULL, 'Canada', ARRAY['Stoneham Snowboard Jamboree','Quebec City Snowboard Jamboree']::text[], ARRAY['big-air','slopestyle','halfpipe']::text[], ARRAY['https://www.skicanada.org/snowboard-world-cup-returns-stoneham-quebec-city/','https://www.skicanada.org/stoneham-snowboard-jamboree-now-world-cup-event/','https://snowboardmag.com/news/quebec-city-snowboard-jamboree-festival-back-for-10th-edition','https://www.snowboardquebec.com/2014/snowboard-jamboree/','https://www.firsttracksonline.com/2015/10/01/quebecs-world-cup-jamboree-goes-urban/']::text[], 'verified'),
  ('snowboard-masters-japan', 'SNOWBOARD MASTERS', 'annual', NULL, NULL, 'Japanese mass-participation contest normally judged on freeride performance plus an obstacle slalom, open to Japan-resident riders aged 18 and over with reduced entry for JSBA and PSA members. In 2024 it ran instead as SBM BANKED+, a straight banked slalom, because conditions prevented building the usual courses.', 'grassroots-contest', 'active', 'independent', 'japan', NULL, 'Japan', ARRAY['SBM']::text[], ARRAY['banked-slalom','slalom','other']::text[], ARRAY['https://steep.jp/en/custom/sbmbanked/']::text[], 'likely'),
  ('snowboard-world-cup-pre-fis', 'Snowboard World Cup (pre-FIS)', 'tour', 1987, NULL, 'The first international snowboard tour, created when NASBA (formed 8 March 1987) partnered with the Snowboard European Association to merge the rival American and European world championships into one circuit. Multiple accounts say the first season ran two events in the United States and two in Europe, with O''Neill, Suzuki and Swatch as sponsors. Later absorbed into the ISF World Tour.', 'tour-series', 'defunct', 'NASBA / Snowboard European Association, later ISF', 'global', NULL, 'multiple', NULL, ARRAY['halfpipe','slalom','giant-slalom']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://www.carvers.it/storia-inglese/','https://snowbrains.com/snowboarding-pioneer-paul-alden-dies-aged-89/','https://www.tetonvalleynews.net/townnews/sport/a-founding-figure-of-organized-competitive-snowboarding-has-passed/article_db455d7f-ed68-46f1-a971-050e55e36410.amp.html']::text[], 'likely'),
  ('speed-nation-alpine-tour', 'Speed Nation Alpine Tour', 'tour', NULL, NULL, 'Canada Snowboard''s national alpine (racing) tour. Recurring stops have included Le Relais at Lac-Beauport, Toronto Ski Club at Collingwood, Alpine Ski Club and Blue Mountain, with Blue Mountain hosting the alpine national championship in 2018 and 2019.', 'tour-series', 'active', 'Canada Snowboard', 'north-america', NULL, 'Canada', ARRAY['Sport Chek Speed Nation Alpine Tour']::text[], ARRAY['parallel-giant-slalom','parallel-slalom']::text[], ARRAY['https://www.canadasnowboard.ca/en/events/','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259']::text[], 'verified'),
  ('speed-nation-sbx-tour', 'Speed Nation Snowboardcross Tour', 'tour', NULL, NULL, 'Canada Snowboard''s national snowboardcross tour. Recurring stops have included Big White, Panorama, Sun Peaks, Craigleith, Horseshoe Valley, Mont Orignal and Mont Sainte-Anne, with a stop designated as the Canadian snowboardcross championship.', 'tour-series', 'active', 'Canada Snowboard', 'north-america', NULL, 'Canada', ARRAY['Sport Chek Speed Nation Snowboardcross Tour']::text[], ARRAY['boardercross']::text[], ARRAY['https://www.canadasnowboard.ca/en/events/sbxtour/','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259']::text[], 'verified'),
  ('spring-battle', 'Spring Battle', 'annual', 2002, NULL, 'Spring park contest at Absolut Park Flachauwinkl, running since 2002 per the organiser''s own site. Originally a Swatch TTR event; by 2025 a WSF Elite Level Event feeding the World Snowboard Points List, judged from multi-day single-take follow-cam footage rather than live runs.', 'major-contest', 'active', 'independent', 'europe', 'Absolut Park, Flachauwinkl', 'Austria', ARRAY['Absolut Park Spring Battle']::text[], ARRAY['slopestyle','rail-jam']::text[], ARRAY['https://www.absolutpark.com/en/spring-battle-25/','https://onboardmag.com/news/snowboarding-events/absolut-park-spring-battle-2007-snowboard.html']::text[], 'likely'),
  ('stylewars-australia', 'StyleWars', 'annual', NULL, NULL, 'Australia''s biggest Swatch TTR tour event, founded and run by Richard Hegarty at Falls Creek in Victoria. Rated 3-Star in 2007 and 4-Star by 2008-2011; in 2011 the organiser referred to ''the past 10 years running'', implying a start around 2001-2002. Sebastien Toutant''s 2009 win here made him the youngest rider to top the TTR ranking.', 'major-contest', 'unconfirmed', 'independent', 'oceania', 'Falls Creek, Victoria', 'Australia', ARRAY['Oakley StyleWars']::text[], ARRAY['slopestyle','rail-jam']::text[], ARRAY['https://www.worldsnowboardfederation.org/events-in-australia/','https://www.worldsnowboardfederation.org/stylewars-2011-australia/','https://www.worldsnowboardfederation.org/?s=Stylewars']::text[], 'likely'),
  ('sugarloaf-banked-slalom', 'Sugarloaf Banked Slalom', 'annual', NULL, NULL, 'Maine banked slalom at Sugarloaf, also referred to as the Mike Baker Banked Slalom. The 2026 edition is listed for March 21.', 'grassroots-contest', 'active', 'independent', 'north-america', 'Sugarloaf', 'USA', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('suomi-tour', 'Suomi Tour', 'tour', NULL, NULL, 'The Finnish Snowboard Association''s national contest tour, with Grom, Rookie and Open divisions plus a Burton Riglet park and coaching for first-time competitors. The tour''s regional stops culminate in the Finnish national championships (SM) at Ruka.', 'tour-series', 'unconfirmed', 'Finnish Snowboard Association (FSA)', 'europe', NULL, 'Finland', NULL, ARRAY['slopestyle','halfpipe']::text[], ARRAY['https://www.worldsnowboardfederation.org/suomi-tour-finland/']::text[], 'likely'),
  ('swiss-snowboard-championships', 'Swiss Snowboard Championships', 'annual', 1986, NULL, 'Switzerland''s national snowboard titles in freestyle, boardercross and race, run at the end of the Swiss-Ski Audi Snowboard Series season at rotating venues.', 'national-championship', 'unconfirmed', 'Swiss-Ski', 'europe', 'St. Moritz', 'Switzerland', NULL, ARRAY['slopestyle','halfpipe','boardercross','other']::text[], ARRAY['https://www.worldsnowboardfederation.org/audi-snowboard-series/','https://www.carvers.it/storia-inglese/']::text[], 'likely'),
  ('tenjin-banked-slalom', 'Tenjin Banked Slalom', 'annual', 2012, NULL, 'Mt Baker-inspired banked slalom on Mt Tanigawa above Minakami, Gunma, reached by tram and organised by former pro rider Yosuke Nishida of the TJ brand. First run in 2012; by 2017 it drew over 400 people across two days and opened with a ceremony praying for safety on an avalanche-prone mountain.', 'grassroots-contest', 'unconfirmed', 'independent', 'japan', 'Tanigawadake Tenjindaira Ski Resort', 'Japan', NULL, ARRAY['banked-slalom']::text[], ARRAY['https://www.worldsnowboardfederation.org/wsf-support-banked-slalom-all-around/','https://www.worldsnowboardfederation.org/2015-tenjin-banked-slalom/','https://www.worldsnowboardfederation.org/photogallery-and-results-from-2016-tenjin-banked-slalom/','https://www.worldsnowboardfederation.org/tenjin-banked-slalom-2017/']::text[], 'verified'),
  ('the-arctic-challenge', 'The Arctic Challenge', 'annual', 1999, 2014, 'Founded in 1999 by Norwegian pros Terje Haakonsen and Daniel Franck as a rider-run alternative to contests they saw as shaped by TV coverage and major sponsors. It ran at locations north of the Arctic Circle in its early years before moving to the Oslo area from 2006. It was one of the events the TTR tour was built around and was the only 6Star-rated event owned by a professional rider, with a USD 100,000 purse and 1000 TTR points to the winner. Terje set a quarterpipe air record of 9.8 m above the lip at the 2007 edition, beating Heikki Sorsa''s 9.3 m from 2001.', 'major-contest', 'dormant', 'independent', 'europe', NULL, 'Norway', ARRAY['Oakley Arctic Challenge']::text[], ARRAY['halfpipe','quarterpipe','slopestyle','freeride','other']::text[], ARRAY['https://en.wikipedia.org/wiki/Arctic_Challenge','https://www.the-house.com/portal/the-history-of-the-oakley-arctic-challenge/','https://www.the-arctic-challenge.com/','https://whitelines.com/archive/news/terje-haakonsen-releases-new-statement-on-the-arctic-challenge.html']::text[], 'verified'),
  ('the-brits', 'The BRITS', 'annual', 1990, NULL, 'Britain''s national snowboard championships, founded in 1990 and described by the World Snowboard Federation as Europe''s longest established winter snowsports festival (20th birthday in 2009). Started in Scotland, spent roughly three decades at Alpine host resorts including Laax, and returned to Cairngorm in 2023 for the first time in 32 years. Now run alongside the British Freeski Championships.', 'national-championship', 'active', 'independent', 'europe', NULL, 'United Kingdom', ARRAY['British Snowboard Championships','British Snowboard and Freeski Championships']::text[], ARRAY['slopestyle','halfpipe','big-air','boardercross','banked-slalom','rail-jam']::text[], ARRAY['https://planetski.eu/2023/02/02/the-brits-heads-back-to-its-roots-in-scotland/','https://www.worldsnowboardfederation.org/news/the-brits-2009-in-laax/']::text[], 'verified'),
  ('toyota-big-air', 'Toyota Big Air', 'annual', 1997, 2014, 'Long-running Japanese stadium big air, 18 editions from 1997 to 2014, normally held around 11 February and shifted to late January or late February in Olympic years. Held at the Makomanai open-air stadium in Sapporo (branded Makomanai Sekisui Heim Stadium from 2007) for its first 15 editions, then moved indoors to the Sapporo Dome from 2012 with a 36 m temporary in-run scaffold. The organising office announced on 30 September 2014 that the event would not continue after the 18th edition.', 'major-contest', 'defunct', 'independent', 'japan', 'Sapporo', 'Japan', NULL, ARRAY['big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/Toyota_Big_Air','https://ja.wikipedia.org/wiki/TOYOTA_BIG_AIR']::text[], 'verified'),
  ('transworld-team-challenge', 'TransWorld Team Challenge', 'annual', 1999, NULL, 'Team-format contest launched by TransWorld SNOWboarding at Snow Summit, California in 1999 and won by the Atlantis team; TransWorld says it ran for ten years before becoming the Team Shoot Out.', 'grassroots-contest', 'defunct', 'independent', 'north-america', 'Snow Summit', 'USA', ARRAY['TransWorld Team Shoot Out']::text[], ARRAY['team']::text[], ARRAY['https://www.snowboarder.com/news/three-decades-transworld-snowboarding-part-2-1997-2006']::text[], 'likely'),
  ('transworld-transam', 'TransWorld TransAm', 'tour', 2003, NULL, 'TransWorld SNOWboarding''s travelling American amateur contest series, launched in 2003 and run for 13 seasons. TransWorld names Lucas Magoon, Chas Guldemond, Gabi Viteri and Matt Ladley among its winners. Stops, disciplines and per-year dates were not sourced in this pass.', 'tour-series', 'defunct', 'independent', 'north-america', NULL, 'USA', NULL, NULL, ARRAY['https://www.snowboarder.com/news/three-decades-transworld-snowboarding-part-2-1997-2006']::text[], 'likely'),
  ('ttr-world-snowboard-tour', 'TTR World Snowboard Tour', 'tour', 2002, 2017, 'Rider- and brand-founded independent world tour set up in 2002 by Terje Haakonsen, event organisers and brand representatives to link the leading independent snowboard contests after the International Snowboarding Federation collapsed the same year. It ranked events on a 1-to-6 star scale that set the points on offer: a 6Star win paid 1000 points, 5Star 850, 4Star 500, 3Star 400, 2Star 200 and 1Star 100, with riders needing six counting scores and the season ranking taken as the average of those six. A women''s tour was added for the 2006/07 season. From the 2013/14 season the six star tiers were replaced by four categories - Regional, National, International and Elite. The TTR name was dropped for ''World Snowboard Tour'' from the 2012/13 season, and the tour brand ceased to exist when TTR Pro Snowboarding and the World Snowboard Federation merged into a single organisation, announced 25 May 2017 and legally completed at an Extraordinary General Assembly in Zurich in October 2017; the merged body offered direct membership from the 2017/18 season instead of running the tour.', 'tour-series', 'defunct', 'TTR Pro Snowboarding', 'global', NULL, 'multiple', ARRAY['Ticket to Ride (TTR) Tour','Swatch TTR World Snowboard Tour','World Snowboard Tour']::text[], ARRAY['halfpipe','slopestyle','big-air','quarterpipe']::text[], ARRAY['https://www.worldsnowboardfederation.org/inside-wsf/history/','https://de.wikipedia.org/wiki/TTR_World_Snowboard_Tour','https://coolerlifestyle.com/news/everything-you-wanted-to-know-about-the-ttr-but-were-afraid-to-ask.html','https://whitelines.com/archive/news/ttr-rebrands-to-world-snowboard-tour.html','https://www.worldsnowboardfederation.org/news/ttr-world-tour-becomes-world-snowboard-tour/','https://www.sgieurope.com/world-snowboarding-will-replace-the-world-snowboard-tour/60795.article','https://www.worldsnowboardfederation.org/ttr-pro-snowboarding-and-world-snowboard-federation-create-one-joint-organisation/','https://www.worldsnowboardfederation.org/ttr-women-tour-announced/']::text[], 'verified'),
  ('us-open-snowboarding', 'Burton US Open Snowboarding Championships', 'annual', 1982, 2020, 'The longest-running snowboard contest in the sport and the flagship of Burton''s contest programme. Burton''s own history page dates the lineage to the 1982 National Snowsurfing Championships at Suicide Six, Vermont; other archives treat that Paul Graves event as a separate contest and date the US Open lineage to Jake Burton Carpenter''s 1983 National Snowboarding Championships at Snow Valley, Vermont. The event took the US Open name at Stratton Mountain in 1985, ran there through 2012, moved to Vail in 2013, and was last held in 2020; the 2021 edition was cancelled and Vail confirmed it would not return.', 'major-contest', 'dormant', 'brand-run', 'north-america', NULL, 'USA', ARRAY['National Snowsurfing Championships','National Snowboarding Championships','US Open Snowboarding Championships']::text[], ARRAY['slalom','downhill','halfpipe','superpipe','quarterpipe','slopestyle','big-air','boardercross','rail-jam','other']::text[], ARRAY['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.burton.com/en-us/blogs/the-burton-blog/13-firsts-us-open-snowboarding-championships','https://thesnowpros.org/2024/09/from-the-archives-great-moments-in-snowboarding-history-part-2/','https://www.firsttracksonline.com/2002/03/03/the-u-s-open-snowboarding-championships-back-to-where-it-all-began/','https://www.vaildaily.com/news/is-vails-burton-us-open-competition-gone-for-good/','http://www.snowboardinginsouthernvermont.com/woodstock-1982.html','https://www.snurferboy.com/nationalchampionship','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[], 'verified'),
  ('us-snowboarding-grand-prix', 'Toyota U.S. Grand Prix', 'tour', 1996, NULL, 'U.S. Ski & Snowboard''s domestic halfpipe (later halfpipe and slopestyle) series and the official qualifying series for the U.S. Olympic snowboard team. Founded 1996; described by U.S. Snowboarding as the first domestic competition series to offer equal prize money to men and women. Now run as FIS World Cup stops under Toyota title sponsorship.', 'tour-series', 'active', 'FIS', 'north-america', NULL, 'USA', ARRAY['U.S. Snowboarding Grand Prix','Chevrolet U.S. Snowboarding Grand Prix','Sprint U.S. Snowboarding Grand Prix']::text[], ARRAY['halfpipe','superpipe','slopestyle','big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/U.S._Snowboarding_Grand_Prix','https://www.aspensnowmass.com/visit/events/toyota-us-grand-prix','https://www.fis-ski.com/snowboard-park-and-pipe/news/2021-22/toyota-us-grand-prix-halfpipe-world-cup-at-copper-mountain-snowboard']::text[], 'verified'),
  ('usasa-national-championships', 'USASA National Championships', 'annual', 1990, NULL, 'The season-ending national championships of USASA, the American grassroots amateur snowboard (and, since 2011, freeski) association founded in 1988 by Chuck Allen with $500 of seed money from TransWorld SNOWboarding. The first Nationals were held in 1990; early editions moved between small mountains in Vermont and Maine and hills in Oregon and California, and Copper Mountain, Colorado has been the permanent home since 2008. Athletes qualify through regional series. USASA states nearly all of the U.S. Olympic snowboard and freeski team began in its events.', 'national-championship', 'active', 'USASA', 'north-america', 'Copper Mountain', 'USA', ARRAY['United States Amateur Snowboarding Association National Championships']::text[], ARRAY['halfpipe','slopestyle','boardercross','giant-slalom','slalom','rail-jam']::text[], ARRAY['https://usasa.org/about-us/history/','https://usasa.org/national-championships/','https://www.townoffrisco.com/event/copper-mountain-events/usasa-snowboard-national-championships/','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s']::text[], 'verified'),
  ('usasa-regional-series', 'USASA Regional Series', 'tour', NULL, NULL, 'The regional competition structure that feeds the USASA National Championships. USASA groups 32 local divisions nationwide into five regional series - Rockies (Utah, Arizona, Colorado, New Mexico), Western (Alaska, Mt. Hood area of Oregon, Lake Tahoe), Central (Great Lakes), Eastern (New York and the Adirondacks) and New England. Each local division runs its own season of events; this is the layer at which most American amateur snowboarders actually competed.', 'tour-series', 'active', 'USASA', 'north-america', NULL, 'USA', NULL, ARRAY['halfpipe','slopestyle','boardercross','giant-slalom','slalom','rail-jam']::text[], ARRAY['https://usasa.org/regional/','https://www.townoffrisco.com/event/copper-mountain-events/usasa-snowboard-national-championships/']::text[], 'verified'),
  ('vans-triple-crown-of-snowboarding', 'Vans Triple Crown of Snowboarding', 'tour', NULL, NULL, 'Vans-run three-stop North American tour with an overall men''s and women''s title decided across the series. The 1999/2000 season ran boardercross, big air and halfpipe at Breckenridge, snowboard cross and halfpipe at Mount Seymour in British Columbia, and halfpipe at Sierra-at-Tahoe, with a USD 10,000 overall prize.', 'tour-series', 'defunct', 'brand-run', 'north-america', NULL, 'United States', NULL, ARRAY['halfpipe','big-air','boardercross']::text[], ARRAY['https://www.mountainzone.com/snowboarding/2000/vans/index.html','https://www.mountainzone.com/snowboarding/2000/vans/breckenridge/']::text[], 'likely'),
  ('waengl-taengl', 'Vans Waengl Taengl', 'annual', 2002, NULL, 'Week-long team-based snowboard ''contest-ival'' in Mayrhofen run by the Austrian Aesthetiker crew, blending a team snowboard contest with team skate, music and art. The World Snowboard Federation gives 2002 as the founding year and 2012 as the tenth-anniversary edition. The Aesthetiker announced a break for 2013 to rework the format.', 'legacy-contest', 'dormant', 'independent', 'europe', 'Mayrhofen, Zillertal', 'Austria', ARRAY['Aesthetiker Waengl Taengl']::text[], ARRAY['team','slopestyle']::text[], ARRAY['https://www.vice.com/de/article/waengl-taengl-ueberrollt-mayrhofen/','https://www.worldsnowboardfederation.org/news/the-asthetikers-announce-a-break-from-the-wangl-tangl-in-2013/']::text[], 'likely'),
  ('whistler-blackcomb-fis-snowboard-world-cup', 'FIS Snowboard World Cup - Whistler Blackcomb', 'annual', NULL, NULL, 'Whistler Blackcomb''s international race stop. A December 2001 World Cup ran snowboard cross, two halfpipes, alpine and big air over six days. Whistler Blackcomb also staged the 2005 FIS Snowboarding World Championships (16-22 January 2005), the first time that championship was held outside Europe, and continues to host FIS-level slopestyle competitions.', 'tour-stop', 'unconfirmed', 'FIS', 'north-america', 'Whistler Blackcomb', 'Canada', NULL, ARRAY['boardercross','halfpipe','big-air','parallel-giant-slalom','slopestyle']::text[], ARRAY['https://www.piquenewsmagazine.com/local-sports/whistler-the-year-in-sports-2461092','https://en.wikipedia.org/wiki/FIS_Snowboarding_World_Championships_2005','https://www.fis-ski.com/DB/general/event-details.html?sectorcode=SB&eventid=55267&seasoncode=2024']::text[], 'likely'),
  ('winsport-calgary-world-cup', 'WinSport Canada Olympic Park FIS World Cup (Calgary)', 'annual', NULL, NULL, 'Calgary''s World Cup stop on the 1988 Olympic site, run on WinSport''s 22-foot halfpipe and slopestyle course. Branded the Halfpipe Rodeo in 2019. The same venue hosts Canada Snowboard''s Air Nation halfpipe national championship and hosted snowboarding at the 2019 Canada Winter Games.', 'tour-stop', 'active', 'FIS', 'north-america', 'WinSport Canada Olympic Park', 'Canada', ARRAY['Halfpipe Rodeo FIS Ski & Snowboard World Cup']::text[], ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.canadasnowboard.ca/en/news/?id=1256','https://www.canadasnowboard.ca/en/news/?id=1259','https://olympic.ca/2019/10/24/winter-competitions-coming-to-canada-in-2019-20/','https://www.canadasnowboard.ca/en/events/freestyletour/nationalsfree/']::text[], 'verified'),
  ('winter-dew-tour', 'Winter Dew Tour', 'tour', 2008, 2024, 'Mountain Dew-backed, NBC-broadcast winter park-and-pipe tour launched for the 2008-09 season with three stops. Reduced to a single mountain championship from the 2012-13 season. Based at Breckenridge for eleven editions (2008-2018), then Copper Mountain (2020-2024). Served as a US Ski & Snowboard Olympic qualifying event in several seasons. Discontinued after the March 2024 edition.', 'tour-series', 'defunct', 'brand-run', 'north-america', NULL, 'USA', ARRAY['AST Dew Tour (winter)','Winter Dew Tour presented by Toyota']::text[], ARRAY['superpipe','slopestyle','jib','team','other']::text[], ARRAY['https://en.wikipedia.org/wiki/Dew_Tour','https://news.vailresorts.com/2008-11-21-WINTER-DEW-TOUR-TO-VISIT-BRECKENRIDGE-RESORT,-DEC-18-21','https://news.vailresorts.com/2018-06-07-Winter-Dew-Tour-Returns-to-Breckenridge-December-13-16,-2018','https://www.mensjournal.com/adventure/winter-dew-tour-heads-to-copper-mountain-colorado-february-6-9-2020/']::text[], 'verified'),
  ('winter-games-nz', 'Winter Games NZ', 'annual', 2009, 2024, 'The Southern Hemisphere''s largest snow sports event, staged in the Southern Lakes district around Wanaka and Queenstown. Biennial from 2009 to 2017, annual from 2018; 11 editions in total. Over its life it hosted 23 FIS Snowboard World Cups and 20 FIS Freeski World Cups plus ANC Cups, Freeride World Qualifiers and FIS Junior World Championships, and from 2020 added the athlete-focused Obsidian team format. Wound up on 23 January 2025, the trust citing event delivery costs, the NZ sponsorship and media market, international federation sanctioning fees and prize money indexed to European currencies.', 'major-contest', 'defunct', 'independent (Winter Games NZ Trust)', 'oceania', NULL, 'New Zealand', ARRAY['New Zealand Winter Games','100% Pure New Zealand Winter Games']::text[], ARRAY['halfpipe','slopestyle','big-air']::text[], ARRAY['https://planetski.eu/2025/01/23/winter-games-nz-ends/','https://www.wintergamesnz.kiwi/about-1','https://en.wikipedia.org/wiki/New_Zealand_Winter_Games']::text[], 'verified'),
  ('winter-x-games', 'Winter X Games (Aspen)', 'annual', 1997, NULL, 'ESPN''s made-for-broadcast winter contest, first held 1997 at Big Bear Lake, California. Moved to Crested Butte (1998-99) and Mount Snow (2000-01) before settling at Buttermilk Mountain in Aspen from 2002 onward. Introduced the superpipe format to snowboard contests and, from 2019, the Knuckle Huck.', 'major-contest', 'active', 'ESPN', 'north-america', 'Buttermilk Mountain, Aspen', 'USA', ARRAY['Winter X Games','X Games Aspen']::text[], ARRAY['halfpipe','superpipe','slopestyle','big-air','boardercross','jib','rail-jam','dual-slalom','other']::text[], ARRAY['https://en.wikipedia.org/wiki/X_Games','https://snowboardmag.com/stories/history-winter-x-games-part-1','https://www.aspendailynews.com/winter-x-games-a-brief-history/article_3459d151-30c8-5345-a0a9-2837bdfe8211.html','https://www.xgames.com/past-events/']::text[], 'verified'),
  ('winter-x-games-europe', 'Winter X Games Europe', 'annual', 2010, 2013, 'First X Games competition held outside the United States. Run at Tignes, France for four editions (2010-2013), then cut when ESPN scaled back its international X Games expansion.', 'major-contest', 'defunct', 'ESPN', 'europe', 'Tignes', 'France', ARRAY['X Games Tignes']::text[], ARRAY['superpipe','slopestyle']::text[], ARRAY['https://en.wikipedia.org/wiki/Winter_X_Games_Europe','https://www.downdays.eu/events/behind-the-scenes/a-brief-history-of-the-x-games-in-europe/','https://en.wikipedia.org/wiki/Winter_X_Games_XVII']::text[], 'verified'),
  ('winter-youth-olympic-snowboarding', 'Snowboarding at the Winter Youth Olympic Games', 'annual', 2012, NULL, 'Snowboarding has been on the programme since the first Winter Youth Olympic Games at Innsbruck in 2012 (halfpipe and slopestyle only), growing to nine events at Gangwon 2024. RESULTS ARCHIVE for a later pass: Olympedia per-Games event index at https://www.olympedia.org/editions/70/sports/SBD (Lausanne 2020) and https://www.olympedia.org/editions/73/sports/SBD (Gangwon 2024); 2012 and 2016 Olympedia edition ids not yet located - see open_questions.', 'major-contest', 'active', 'IOC (sport governed at the Games by FIS)', 'global', NULL, 'multiple', NULL, ARRAY['halfpipe','slopestyle','boardercross','big-air','team']::text[], ARRAY['http://www.olympedia.org/definitions/70','https://www.olympedia.org/editions/70/sports/SBD','https://www.olympedia.org/editions/73/sports/SBD']::text[], 'verified'),
  ('world-rookie-finals', 'World Rookie Finals', 'annual', NULL, NULL, 'Season-closing event of the World Rookie Tour, held in an Alpine resort in spring, where the World Rookie Champion titles are awarded in the Rookie and Grom divisions. It carried a 3Star TTR rating in 2015. Host resorts have included Ischgl (2015) and Kitzsteinhorn (2025).', 'major-contest', 'active', 'World Snowboard Federation / Black Yeti', 'europe', NULL, 'multiple', ARRAY['Völkl World Rookie Finals','World Rookie Snowboard Finals']::text[], ARRAY['slopestyle','halfpipe','big-air']::text[], ARRAY['https://www.worldrookietour.com/the-tour/','https://www.worldsnowboardfederation.org/world-rookie-snowboard-finals-2025-2/','https://www.worldsnowboardfederation.org/2017-world-rookie-finals-kitzsteinhorn-kaprun/','https://www.worldsnowboardfederation.org/?s=Ischgl']::text[], 'likely'),
  ('world-rookie-tour', 'World Rookie Tour', 'tour', NULL, NULL, 'Global youth freestyle tour organised by the World Snowboard Federation with national snowboard associations, feeding the World Rookie Ranking. Age divisions are Rookie (U18), Grom (U15) and Supergrom (U13); the ranking averages an athlete''s three best results from Level 1-3 Star WSPL events. Stops are branded ''Rookie Fests'' and are spread across Europe, South America, Australia and Japan, with the season closing at the World Rookie Finals. The Livigno World Rookie Fest, the tour''s anchor stop, was in its 19th edition in 2024, which implies a first edition around 2006.', 'tour-series', 'active', 'World Snowboard Federation / Black Yeti', 'global', NULL, 'multiple', NULL, ARRAY['slopestyle','halfpipe','big-air','rail-jam']::text[], ARRAY['https://www.worldsnowboardfederation.org/wsf-projects/world-rookie-tour/','https://www.worldrookietour.com/the-tour/','https://www.worldsnowboardfederation.org/the-new-snowboard-generation-shines-at-livigno-world-rookie-fest-2024/']::text[], 'likely'),
  ('world-ski-snowboard-festival', 'World Ski & Snowboard Festival', 'annual', 1996, NULL, 'Ten-day (later shortened) April festival in Whistler founded by Doug Perry in 1996, growing out of the 1994 World Technical Skiing Championships on Blackcomb. It absorbed the existing spring contests including the WestBeach Classic, the Whistler Cup and the Couloir Extreme, and became the umbrella under which most of Whistler''s spring snowboard contests ran. A 2006 economic impact assessment put its activity at $37.7 million for British Columbia; 2007 attendance was reported at 275,000. Vail Resorts shortened the format after 2018; Gibbons Whistler took full ownership in November 2019.', 'major-contest', 'active', 'independent', 'north-america', 'Whistler Blackcomb', 'Canada', ARRAY['TELUS World Ski & Snowboard Festival','TWSSF']::text[], ARRAY['big-air','slopestyle','halfpipe','rail-jam','freeride','other']::text[], ARRAY['https://whistlermuseum.org/2024/04/09/wssf-the-beginning/','https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival','http://www.watermarkinc.ca/twssfmedia/timecapsule/backgrounder.html','https://wssf.com/','https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx']::text[], 'verified'),
  ('world-snowboarding-championship-whistler', 'World Snowboarding Championship (Whistler)', 'annual', 2001, NULL, 'Independent Whistler championship produced by The Masters Group and backed by WestBeach Sports, which redirected its WestBeach Classic budget into it for 2001. Contested slopestyle, jib jam and superpipe over 19-22 April 2001. Distinct from the FIS Snowboarding World Championships. How many years it ran could not be established.', 'major-contest', 'unconfirmed', 'independent', 'north-america', 'Whistler Blackcomb', 'Canada', NULL, ARRAY['superpipe','slopestyle','jib']::text[], ARRAY['https://www.piquenewsmagazine.com/local-sports/westbeach-classic-not-on-2459602','https://www.piquenewsmagazine.com/local-sports/whistler-the-year-in-sports-2461092']::text[], 'likely'),
  ('world-snowboarding-championships', 'World Snowboarding Championships', 'annual', 2012, NULL, 'Rider-side world championship developed and owned by TTR and the World Snowboard Federation, approved by unanimous vote at the TTR and WSF general assemblies in Barcelona in May 2010. The first edition, in Oslo in February 2012, was described as the first championships run by snowboarders since 1999; the 2011 Oakley Arctic Challenge was staged as its trial event. The local organising company Snowboard-VM 2012 AS was owned by The Arctic Challenge, the Norwegian Snowboard Federation and Oslo Vinterpark.', 'major-contest', 'unconfirmed', 'TTR / World Snowboard Federation', 'global', NULL, 'multiple', ARRAY['TTR World Snowboarding Championships','The World Championships of Snowboarding']::text[], ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://en.wikipedia.org/wiki/2012_World_Snowboarding_Championships','https://www.worldsnowboardfederation.org/the-oakley-arctic-challenge-announces-2011-rider-protocol/','https://www.worldsnowboardfederation.org/ttr-world-snowboarding-championships-2012-highlights/','https://www.worldsnowboardfederation.org/the-world-championships-of-snowboarding-2016-2/']::text[], 'verified'),
  ('world-snowboarding-championships-sims', 'World Snowboarding Championships', 'annual', 1983, NULL, 'Founded by Tom Sims at Soda Springs, California, and the first snowboard contest to include a halfpipe. Sims registered the service mark WORLD SNOWBOARDING CHAMPIONSHIPS with the USPTO (reg. 1530152, filed 8 July 1987) claiming first use in commerce on 15 February 1983. The event moved to Breckenridge, Colorado for 1986 and 1987 and picked up Swatch as title sponsor; a rival European edition ran at Livigno and St Moritz in January 1987.', 'legacy-contest', 'defunct', 'brand-run', 'north-america', NULL, 'USA', ARRAY['Sims World Snowboarding Championships','Swatch World Championships']::text[], ARRAY['halfpipe','slalom','giant-slalom','downhill','mogul','other']::text[], ARRAY['https://trademarks.justia.com/736/70/world-snowboarding-championships-73670866.html','https://www.snowboarder.com/transworld-snowboarding-archive/a-complete-history-of-the-snowboard-halfpipe','https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause','https://www.sierrasun.com/sports/soda-springs-goes-retro-for-tom-sims/','https://www.skihall.com/hall-of-famers/tom-sims/','https://snowbrains.com/snowboarding-pioneer-paul-alden-dies-aged-89/','https://snowbrains.com/breckenridge-resort-co-marks-40-years-of-snowboarding-history-with-new-worlds-competition/']::text[], 'likely'),
  ('wsf-south-america-tour', 'WSF South America Tour', 'tour', NULL, NULL, 'Southern-hemisphere winter circuit that gave South American riders TTR and WSF ranking points, running from an urban rail jam in Santiago through Valle Nevado and El Colorado to an indoor finale in Rio de Janeiro.', 'tour-series', 'unconfirmed', 'WSF (World Snowboard Federation)', 'south-america', NULL, 'multiple', NULL, ARRAY['slopestyle','big-air','rail-jam']::text[], ARRAY['https://www.worldsnowboardfederation.org/winter-season-in-chile/']::text[], 'verified'),
  ('x-games-norway', 'X Games Norway', 'annual', 2016, 2020, 'ESPN''s Norwegian X Games, launched in Oslo in 2016 as the first X Games to stage summer and winter disciplines in one city. Alternated between Oslo (2016, 2018, 2019) and Hafjell (2017, 2020). The 2018 and 2019 Oslo editions were indoor big air held at Telenor Arena, Fornebu, in May and August respectively.', 'major-contest', 'defunct', 'ESPN', 'europe', NULL, 'Norway', ARRAY['X Games Oslo']::text[], ARRAY['superpipe','slopestyle','big-air','other']::text[], ARRAY['http://www.labelnetworks.com/x-games-oslo-to-launch-in-february-2016-bringing-together-both-summer-and-winter-sports/','https://www.firsttracksonline.com/2015/11/09/x-games-expands-to-oslo/','https://de.wikipedia.org/wiki/X-Games_Norway_2017','https://www.hafjellresort.no/en/x-games','https://radseason.com/event/x-games-norway-fornebu-norway/','https://en.wikipedia.org/wiki/X_Games']::text[], 'verified'),
  ('x-trail-jam', 'Nissan X-Trail Jam', 'annual', 2001, NULL, 'Indoor stadium contest launched in the Tokyo Dome in 2001, running a quarterpipe and a straight-jump (big air) event on real snow trucked into the baseball stadium. Reto Lamm - the first Air & Style winner and later TTR Pro Snowboarding president - is credited as president and main developer. It became a TTR 6Star event.', 'major-contest', 'defunct', 'TTR', 'japan', 'Tokyo Dome', 'Japan', ARRAY['X-Trail Jam in Tokyo Dome']::text[], ARRAY['quarterpipe','big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/X-Trail_Jam','https://www.methodmag.com/industry-news/ttr-world-snowboard-tour-6-star-event-nissan-xt.html','https://snowboardnet.jp/x-trail-jam-in-tokyo-dome-3/','https://backside.jp/news-1101/']::text[], 'likely'),
  ('zillertal-valley-ralley', 'Zillertal Vaelley Raelley', 'tour', 2013, NULL, 'Zillertal-based slopestyle tour hosted by Blue Tomato with Zillertal Tourismus and the Aesthetiker snowboard club, feeding the World Snowboard Points List and the World Rookie Ranking. 2025/26 is its 13th season, which places the first season at 2013/14. Its Mayrhofen stop runs in the PenkenPark.', 'tour-series', 'active', 'independent (Blue Tomato / Zillertal Tourismus / Die Aesthetiker)', 'europe', NULL, 'Austria', NULL, ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/zillertal-valley-ralley-announces-new-tour-dates-for-2025-2026/']::text[], 'likely')
